declare namespace SigApi {
    interface SigState {
        /**
         * target (see sigApi.SIG_CONST.STATION_STATE_TARGET_* constants)
         */
        target: number,
        /**
         * type (see sigApi.SIG_CONST.STATION_STATE_TYPE_* constants)
         */
        type: number,
        /**
         * error (see sigApi.SIG_CONST.ERROR_* constants)
         */
        error: number,
        /**
         * raw data depending on type
         */
        data: ArrayBuffer | null,
        /**
         * station (from data)
         */
        station: number,
        /**
         * state (from data) (see sigApi.SIG_CONST.STATION_STATE_* constants)
         */
        state: number
    }
}
